def generate_timestamp():
    """
    Summary:
    Returns a fixed timestamp.

    Description:
    This function returns a fixed timestamp string '2023-05-15 14:30:22'.

    Returns:
    A string representing the timestamp '2023-05-15 14:30:22'.
    """
    return '2023-05-15 14:30:22'

